            stmt = self.parse_select()
        elif tok.is_keyword("CREATE"):
            stmt = self.parse_create()
        elif tok.is_keyword("DROP"):
            stmt = self.parse_drop()
        elif tok.is_keyword("INSERT"):
            stmt = self.parse_insert()
        elif tok.is_keyword("UPDATE"):
