        for k, join in enumerate(clause.joins, start=2):
            pred = None
            if join.on is not None:
                on = ExprCompiler(self.scope, "ON", visible=k)
                pred = as_predicate(on.compile(join.on), "ON")
            self.joins.append((join.kind, pred))
