        key_fns = [fn for _, fn, _ in self.sort_keys if fn is not None]
        if self.grouped:
            envs = self._group_envs(rows)
        else:
            envs = rows
        for env in envs:
            out = tuple(f(env) for f in item_fns)
            results.append((out, [f(env) for f in key_fns]))
        if self.stmt.distinct:
            seen: set = set()
            unique = []
            for res in results:
