            fresh: set = set()
            for row in new_rows:
                val = row[i]
                if val is None:
                    continue
                k = value_key(val)
                if k in keys or k in fresh:
                    raise self._violation(i, val)
                fresh.add(k)
            added[i] = fresh
        for i, fresh in added.items():
            self.unique_keys[i] |= fresh
