class _Source:
    """The rows of one table reference: a stored table, or a derived table's query."""

    def __init__(self, table: Any = None, plan: Optional[Plan] = None,
                 correlated: bool = False) -> None:
        self.table = table
        self.plan = plan
        self.correlated = correlated
        self._cache: Optional[list[tuple]] = None

    def rows(self) -> list[tuple]:
        if self.table is not None:
            return self.table.rows
        if self._cache is not None:
            return self._cache
        rows = self.plan.run()
        if not self.correlated:
            self._cache = rows
        return rows


class SelectPlan:
    """A bound SELECT."""

    def __init__(self, stmt: n.Select, ctx: QueryContext) -> None:
        self.stmt = stmt
        self.ctx = ctx
        self.scope = Scope()
        self.sources: list[_Source] = []
        # each join: (kind, ON predicate or None, equi-join columns or None)
        self.joins: list[tuple[str, Optional[Callable[[tuple], bool]],

    # ------------------------------------------------------------ binding

    def _bind_from(self) -> None:
        clause = self.stmt.from_
        if clause is None:
            return
        refs = [clause.first] + [j.table for j in clause.joins]
        for ref in refs:
            if ref.query is not None:
                sub = self.ctx.derived()
                plan = build_query(ref.query, sub)
                self.ctx.absorb(sub)
                self.scope.add(ref.exposed, plan.columns)
                self.sources.append(_Source(plan=plan, correlated=sub.correlated))
            else:
                table = self.ctx.db.get_table(ref.name)
                self.scope.add(ref.exposed, table.column_names)
                self.sources.append(_Source(table=table))
        for k, join in enumerate(clause.joins, start=2):
            pred = None
            if join.on is not None:
                on = ExprCompiler(self.scope, "ON", self.ctx, visible=k)
                pred = as_predicate(on.compile(join.on), "ON")
            self.joins.append((join.kind, pred, self._equi_columns(join.on, k)))
        if self.stmt.where is not None:
            where = ExprCompiler(self.scope, "WHERE", self.ctx)
            self.where = as_predicate(where.compile(self.stmt.where), "WHERE")

    def _equi_columns(self, on: Optional[n.Expr], k: int) -> Optional[tuple[int, int]]:
        """For ``ON left_col = right_col`` (plain columns of this query, one from the k-th
        source and one from an earlier one): (row index of the left column, column index
        within the right source). Such a join can be done with a hash table."""
        if not (isinstance(on, n.Binary) and on.op == "="
                and isinstance(on.left, n.ColumnRef) and isinstance(on.right, n.ColumnRef)):
            return None
        a, b = self.scope.lookup(on.left), self.scope.lookup(on.right)
        if a is None or b is None:
            return None  # an outer reference
        right = self.scope.sources[k - 1]
        if a[0] == k - 1 and b[0] < k - 1:
            a, b = b, a
        if b[0] != k - 1 or a[0] >= k - 1:
            return None
        return a[1], b[1] - right.offset

    def _bind_items(self) -> None:
        for item in self.stmt.items:
            if isinstance(item, n.Star):
                if self.stmt.from_ is None:
                    raise SQLSyntaxError("SELECT * requires FROM")
                if self.grouped:
                    raise SQLSyntaxError("* is not allowed in a grouped query")
                sources = (self.scope.sources if item.table is None
                           else [self.scope.source(item.table)])
                for src in sources:
                    for i, name in enumerate(src.columns):
                        idx = src.offset + i
                        self.columns.append(name)
                        self.item_fns.append(lambda env, idx=idx: env[idx])
                continue
            if self.stmt.distinct:
                raise SQLSyntaxError("with SELECT DISTINCT, ORDER BY items must be output "
                                     "columns")
            self.sort_keys.append((None, self.compiler.compile(item.expr), item.desc))

    # ------------------------------------------------------------ execution

    def _source_rows(self) -> list[tuple]:
        if not self.sources:
            return [()]
        rows = [tuple(r) for r in self.sources[0].rows()]
        for source, src_scope, (kind, pred, equi) in zip(self.sources[1:],
                                                         self.scope.sources[1:], self.joins):
            right = source.rows()
            nulls = (None,) * len(src_scope.columns)
            if equi is not None:
                rows = _hash_join(rows, right, equi, kind == "LEFT", nulls)
                continue
            joined = []
            for left in rows:
                matched = False
                for r in right:
                    combined = left + r
                    if pred is None or pred(combined):
                        joined.append(combined)
                        matched = True
                if kind == "LEFT" and not matched:
                    joined.append(left + nulls)
            rows = joined
        return rows

    def run(self) -> list[tuple]:
        rows = self._source_rows()
        if self.where is not None:
            where = self.where
            rows = [r for r in rows if where(r)]
        item_fns = self.item_fns
        key_fns = [fn for _, fn, _ in self.sort_keys if fn is not None]

