@pytest.mark.parametrize("seed", range(10))
def test_bulk_changes_keep_indexes_consistent(seed):
    """Large INSERT / UPDATE / DELETE batches take the bulk index maintenance paths."""
    r = random.Random(seed)
    engine = Engine()
    for t in ("ix", "plain"):
        engine.execute(f"CREATE TABLE {t} (id INT, k INT, b BOOLEAN)")
    for col in ("id", "k", "b"):
        engine.execute(f"CREATE INDEX ix_{col} ON ix ({col})")
    rows = ", ".join(f"({i}, {r.randint(0, 5)}, {r.choice(['TRUE', 'FALSE', 'NULL'])})"
                     for i in range(300))
    statements = [f"INSERT INTO {{t}} VALUES {rows}"]
    for _ in range(8):
        m = r.randint(2, 4)
        statements.append(r.choice([
            f"UPDATE {{t}} SET k = (k + {r.randint(1, 3)}) % 7 WHERE id % {m} <> 0",
            f"UPDATE {{t}} SET b = NOT b WHERE k < {r.randint(1, 6)}",
            f"UPDATE {{t}} SET id = 1000 - id WHERE id % {m} = 0",
            f"DELETE FROM {{t}} WHERE k = {r.randint(0, 6)} AND id % {m} = 0",
            f"INSERT INTO {{t}} SELECT id + 2000, k, b FROM {{t}} WHERE id % {m} = 1",
        ]))
    for template in statements:
        assert engine.execute(template.format(t="ix")) == engine.execute(template.format(t="plain"))
        for pred in ("k = 3", "k >= 2 AND k < 5", "b = TRUE", "b < TRUE", "id > 500",
                     "id BETWEEN 100 AND 200"):
            assert engine.execute(f"SELECT * FROM ix WHERE {pred}") == \
                engine.execute(f"SELECT * FROM plain WHERE {pred}"), (template, pred)
