import random, sqlite3, sys, math
sys.path.insert(0, '.')
from minidb.engine import Engine
from minidb.protocol import DBError, SQLRuntimeError

TEXTS = ["'a'", "'b'", "'ab'", "'B'", "''", "'é'", "'a b'", "'zz'", "NULL"]
REALS = ["0.5", "1.5", "-2.25", "3.0", "0.1", "NULL", "2.5"]

def texpr(r, d=0):
    k = r.random()
    if d > 1 or k < 0.4: return r.choice(["s", "s", "t2.u", "'x'", "'b'"])
    if k < 0.6: return f"({texpr(r, d+1)} || {texpr(r, d+1)})"
    if k < 0.75: return f"REPLACE({texpr(r, d+1)}, 'a', 'q')"
    return f"COALESCE({texpr(r, d+1)}, 'n')"

def rexpr(r, d=0):
    k = r.random()
    if d > 1 or k < 0.4: return r.choice(["v", "v", "t2.w", "0.5", "2.0", "-1.5"])
    if k < 0.6: return f"({rexpr(r, d+1)} {r.choice(['+','-','*'])} {rexpr(r, d+1)})"
    if k < 0.7: return f"CAST(LENGTH({texpr(r, d+1)}) AS REAL)"
    return f"ABS({rexpr(r, d+1)})"

def cond(r):
    k = r.random()
    if k < 0.4: return f"{texpr(r)} {r.choice(['=','<','>=','<>'])} {texpr(r)}"
    if k < 0.75: return f"{rexpr(r)} {r.choice(['=','<','>='])} {rexpr(r)}"
    if k < 0.85: return f"s IS {r.choice(['', 'NOT '])}NULL"
    return f"({cond(r)} {r.choice(['AND', 'OR'])} {cond(r)})"

def run(seed):
    r = random.Random(seed)
    m, s = Engine(), sqlite3.connect(":memory:")
    for sql in ["CREATE TABLE t1 (s TEXT, v REAL)", "CREATE TABLE t2 (u TEXT, w REAL)"]:
        m.execute(sql); s.execute(sql)
    for t in ("t1", "t2"):
        rows = ", ".join(f"({r.choice(TEXTS)}, {r.choice(REALS)})" for _ in range(r.randint(0, 7)))
        if rows:
            m.execute(f"INSERT INTO {t} VALUES {rows}"); s.execute(f"INSERT INTO {t} VALUES {rows}")
    if r.random() < 0.5:
        m.execute("CREATE INDEX t2u ON t2 (u)")
    if r.random() < 0.5:
        m.execute("CREATE INDEX t1s ON t1 (s)")
    frm = f"t1 {r.choice(['JOIN', 'LEFT JOIN'])} t2 ON t2.u = t1.s" if r.random() < 0.5 else "t1 CROSS JOIN t2"
    where = f" WHERE {cond(r)}" if r.random() < 0.7 else ""
    kind = r.random()
    ordered = False
    if kind < 0.35:
        q = f"SELECT {texpr(r)}, {rexpr(r)} FROM {frm}{where}"
    elif kind < 0.6:
        q = f"SELECT s, COUNT(*), MIN({texpr(r)}), MAX({rexpr(r)}), COUNT(DISTINCT {texpr(r)}) FROM {frm}{where} GROUP BY s"
    elif kind < 0.8:
        q = f"SELECT DISTINCT {texpr(r)} FROM {frm}{where}"
    else:
        e1 = texpr(r)
        q = f"SELECT {e1}, {rexpr(r)} FROM {frm}{where} ORDER BY 1 DESC, 2"
        ordered = True
    try:
        exp = [list(x) for x in s.execute(q).fetchall()]
    except Exception:
        return
    try:
        got = m.execute(q)["rows"]
    except SQLRuntimeError:
        return
