        self.tables[table.name] = table
        for index in implicit:
            table.indexes.append(index)  # the table is empty: nothing to build
            self.indexes[index.name] = index

        def undo() -> None:
            del self.tables[table.name]
            for index in implicit:
                del self.indexes[index.name]
